/* The same journey, now with places to explore and memories to hold. */
const TOWN_STOPS=[['market',145,236,'星光集市','market'],['memory',335,147,'琉璃回廊','pavilion'],['water',460,300,'水车小径','mill'],['greenhouse',610,157,'月光温室','glass'],['post',760,285,'迷雾邮局','post'],['bridge',890,175,'星光桥','bridge']];
let townWalkFrame=0,townWalkEpoch=0,roomSelection=null,roomDrag=null,roomIgnoreClick=0;
function townState(){let t=campaign.town;if(!t||!Number.isFinite(t.x)||!Number.isFinite(t.y))t=campaign.town={x:70,y:360,seen:[]};t.x=clamp(t.x,35,955);t.y=clamp(t.y,100,390);if(!Array.isArray(t.seen))t.seen=[];return t}
function townHouse(id,x,y,name,type){const done=campaign.done.includes(id),open=cpUnlocked(id),roof=done?'#ce9a8e':'#8d6d8a',light=done?'#ffe2a1':open?'#d7c2a4':'#70687e';let shape='';if(type==='pavilion')shape=`<path d="M-51-46Q0-63 51-46L43-52H-43Z" fill="#8bb8b4"/><path d="M-40-76Q0-88 40-76L31-83H-31Z" fill="#81a6a9"/><path d="M-34-45v45m68-45v45" stroke="#c5aa9f" stroke-width="6"/><rect x="-33" y="-45" width="66" height="45" fill="#af8e9b" opacity=".7"/><rect x="-15" y="-33" width="30" height="33" rx="14" fill="${light}"/>`;else if(type==='bridge')shape=`<path d="M-60-9Q0-49 60-9" stroke="#d9badb" stroke-width="11" fill="none"/><path d="M-60-31Q0-71 60-31" stroke="#9ca0c6" stroke-width="3" fill="none"/><path d="M-50-13v-22m25 10v-23m25 17v-24m25 30v-23m25 35v-22" stroke="#bfc0dc" stroke-width="3"/><g fill="${light}"><circle cx="-50" cy="-37" r="4"/><circle cx="0" cy="-58" r="4"/><circle cx="50" cy="-37" r="4"/></g>`;else{shape=`<rect x="-43" y="-61" width="86" height="65" rx="5" fill="${type==='glass'?'#8ca7a7':'#b596a6'}"/><path d="M-53-61 0-95 53-61Z" fill="${type==='glass'?'#a5c4bc':roof}"/><rect x="-12" y="-29" width="24" height="33" rx="11" fill="#67566f"/><rect x="-33" y="-48" width="17" height="22" rx="3" fill="${light}"/><rect x="16" y="-48" width="17" height="22" rx="3" fill="${light}"/>`;if(type==='glass')shape+=`<path d="M-43-61h86m-22 0v65m-42-65v65M0-95v33" stroke="#d0dccc" stroke-width="2"/>`;if(type==='market')shape+=`<path d="M-48-48h96l-7 16h-82z" fill="#e2aeae"/><path d="M-30-48v16m20-16v16m20-16v16m20-16v16" stroke="#f2d5bd" stroke-width="9"/><circle cx="-58" cy="-37" r="10" fill="${light}"/><path d="M-58-56v9" stroke="#c7a1a1"/>`;if(type==='mill')shape+=`<g class="town-waterwheel ${done?'turning':''}" transform="translate(53 -15)"><circle r="24" fill="#5a516f" stroke="#c4a48e" stroke-width="5"/><path d="M0-23v46M-23 0h46M-16-16l32 32m0-32-32 32" stroke="#c4a48e" stroke-width="3"/></g>`;if(type==='post')shape+=`<rect x="-24" y="-78" width="48" height="19" rx="3" fill="#dec6b0"/><path d="m-15-74 15 9 15-9m-30 0v10h30v-10" fill="none" stroke="#8c728a" stroke-width="2"/>`}
 return `<g class="town-building ${done?'visited':''} ${open?'available':'locked'}" data-town="${id}" transform="translate(${x} ${y})" role="button" tabindex="0" aria-label="走到${name}${open?'':'，尚未解锁'}"><ellipse cy="8" rx="59" ry="12" fill="#201d3b" opacity=".35"/>${done?'<ellipse cy="-25" rx="64" ry="55" fill="url(#townGlow)"/>':''}${shape}<text y="31" text-anchor="middle" fill="${open?'#f7e5ca':'#b5a6bb'}" font-size="13">${done?'✓ ':''}${name}</text>${!open?'<text y="48" text-anchor="middle" fill="#aa9bb3" font-size="10">前方还有一段路</text>':''}</g>`
}
cpMapArt=function(){const t=townState();return `<div class="town-scene"><svg id="townWorld" viewBox="0 0 1000 440" aria-label="可探索的暮光小镇，点街道散步，点建筑前往"><defs>${daylightDefs}<linearGradient id="townSky" x2="0" y2="1"><stop stop-color="#252642"/><stop offset="1" stop-color="#79627e"/></linearGradient><radialGradient id="townGlow"><stop stop-color="#f4d89d" stop-opacity=".4"/><stop offset="1" stop-color="#f4d89d" stop-opacity="0"/></radialGradient></defs><rect width="1000" height="440" fill="url(#townSky)"/><circle cx="837" cy="51" r="28" fill="#f7e1b0"/><circle cx="848" cy="43" r="25" fill="#35314e"/><g fill="#ead9bf">${Array.from({length:20},(_,i)=>`<circle cx="${(i*149+36)%980}" cy="${15+(i*37)%95}" r="${i%3===0?1.7:1}" class="town-star" style="animation-delay:-${i%5}s"/>`).join('')}</g><path d="M0 152Q120 65 235 145T475 134T745 132T1000 120V440H0" fill="#49445e"/><path d="M0 224Q150 155 300 219T600 205T1000 208V440H0" fill="#585069"/><path d="M0 385Q170 287 333 339T600 318T1000 360V440H0" fill="#6e5d76"/><path d="M430 440Q540 380 505 290T555 215" stroke="#668b9f" stroke-width="34" opacity=".6" fill="none"/><path d="M430 440Q540 380 505 290T555 215" stroke="#afc4d0" stroke-width="2" stroke-dasharray="10 18" opacity=".6" fill="none"/><path d="M55 366 145 251 335 162 460 315 610 172 760 300 890 190" fill="none" stroke="#b39ca3" stroke-width="24" stroke-linecap="round" stroke-linejoin="round"/><path d="M55 366 145 251 335 162 460 315 610 172 760 300 890 190" fill="none" stroke="#d8bfba" stroke-width="2" stroke-dasharray="1 12" stroke-linecap="round" opacity=".65"/>${TOWN_STOPS.map(p=>townHouse(...p)).join('')}<g data-town-extra="lamp" role="button" tabindex="0" aria-label="看看路灯" transform="translate(268 276)"><circle cy="-49" r="35" fill="url(#townGlow)"/><path d="M0 0v-45" stroke="#c2a8b3" stroke-width="4"/><rect x="-9" y="-62" width="18" height="23" rx="5" fill="#f7d799"/><path d="M-14-63h28" stroke="#c2a8b3" stroke-width="3"/></g><g data-town-extra="bench" role="button" tabindex="0" aria-label="一起坐在长椅" transform="translate(655 352)"><path d="M-30-18h60m-60 9h60m-50 8v14m40-14v14" stroke="#ccb09d" stroke-width="6"/></g><g data-town-extra="cat" role="button" tabindex="0" aria-label="看看小猫" transform="translate(90 319)"><ellipse cy="-5" rx="13" ry="9" fill="#dfcbb6"/><circle cx="-8" cy="-15" r="8" fill="#dfcbb6"/><path d="m-15-19 1-8 6 6m1 1 5-6 1 9" fill="#dfcbb6"/><path d="M11-4q18-18 14-1" fill="none" stroke="#dfcbb6" stroke-width="4"/><circle cx="-10" cy="-16" r="1" fill="#53465a"/></g><g id="townPair" transform="translate(${t.x} ${t.y})"><path d="M5 0h32" stroke="#ecc4a7" stroke-width="4" stroke-linecap="round"/>${character(-14,0,true)+character(35,0,false)}</g><g fill="#f6d59f" pointer-events="none">${[0,1,2,3,4,5].map(i=>`<circle cx="${180+i*127}" cy="${230+(i*39)%120}" r="2" class="town-firefly" style="animation-delay:-${i}s"/>`).join('')}</g></svg><span class="town-map-instruction">点街道一起散步 · 点建筑走到门口</span></div><div class="town-conversation" id="townConversation" role="status"><span class="town-speaker">牵着你的小向导</span><p>灯都还亮着。想先去哪里？路灯、长椅和小猫，也可以打声招呼。</p></div>`};
function townSay(s,action=''){const box=document.querySelector('#townConversation');if(box)box.innerHTML=`<span class="town-speaker">小镇悄悄话</span><p>${s}</p>${action}`}
function townWalk(x,y,arrive){cancelAnimationFrame(townWalkFrame);const epoch=++townWalkEpoch,t=townState(),from={x:t.x,y:t.y},pair=document.querySelector('#townPair');if(!pair)return;pair.classList.add('walking');const duration=motionOff()?0:clamp(Math.hypot(x-t.x,y-t.y)*2.1,280,1100);let start=null;function step(now){if(epoch!==townWalkEpoch||!pair.isConnected)return;if(start===null)start=now;const p=duration?Math.min(1,(now-start)/duration):1,u=p*p*(3-2*p);t.x=from.x+(x-from.x)*u;t.y=from.y+(y-from.y)*u;pair.setAttribute('transform',`translate(${t.x} ${t.y})`);if(p<1)townWalkFrame=requestAnimationFrame(step);else{pair.classList.remove('walking');cpSave();arrive?.()}}townWalkFrame=requestAnimationFrame(step)}
function townVisit(id){const p=TOWN_STOPS.find(p=>p[0]===id);if(!p)return;townSay('来了，等我牵着你走过去。');townWalk(p[1]-15,p[2]+43,()=>{if(!cpUnlocked(id)){townSay('这里的灯还在等我们。先收好前一站的回忆，再一起回来。');return}const complete=campaign.done.includes(id),lines={market:complete?'摊主：又见面啦。你们的合照，要好好带回家呀。':'摊主：欢迎光临。这里的三件小事，要靠你们一起解开。',memory:complete?'琉璃色的光还在。十一去北京的那张合照，也还在回忆册里。':'这一道琉璃色的光，像不像我们十一去北京的那一天？',water:complete?'水车还在转。听，是我们一起找回来的水声。':'水车停了，风也绕了路。一起替小镇把它们找回来吧。',greenhouse:complete?'花匠：花又开了。上次那束喜欢，你们好好收着了吗？':'花匠：给花接上水、调好月光，再一起采下星星。',post:complete?'邮差：上次的信送到了。这次，也要记得把话说给对方听。':'邮差：一人读线索，一人来解锁。这封信，等你们一起送到。',bridge:complete?'桥上的光还没有熄。想再牵着手走一遍吗？':'三颗星都到齐了。接下来的桥，需要你们轮流接住彼此。'};townSay(lines[id],`<button id="townEnter" class="primary">${complete?'再去看看':'一起进去'} · ${p[3]} →</button>`);document.querySelector('#townEnter').onclick=()=>cpStart(id)})}
function townBind(){const svg=document.querySelector('#townWorld');if(!svg)return;svg.querySelectorAll('[data-town],[data-town-extra]').forEach(g=>{const r=document.createElementNS('http://www.w3.org/2000/svg','rect');r.setAttribute('x',g.dataset.town?'-65':'-35');r.setAttribute('y',g.dataset.town?'-100':'-70');r.setAttribute('width',g.dataset.town?'130':'70');r.setAttribute('height',g.dataset.town?'155':'95');r.setAttribute('fill','transparent');r.setAttribute('pointer-events','all');g.prepend(r)});svg.onclick=e=>{if(e.target.closest('[data-town],[data-town-extra]'))return;const point=svg.createSVGPoint();point.x=e.clientX;point.y=e.clientY;const q=point.matrixTransform(svg.getScreenCTM().inverse());townWalk(clamp(q.x,40,945),clamp(q.y,235,385),()=>townSay('不用急。就这样牵着手，慢慢走，也很好。'))};svg.querySelectorAll('[data-town]').forEach(g=>{const fn=()=>townVisit(g.dataset.town);g.onclick=e=>{e.stopPropagation();fn()};g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fn()}}});svg.querySelectorAll('[data-town-extra]').forEach(g=>{const fn=()=>{const id=g.dataset.townExtra,positions={lamp:[240,308],bench:[625,377],cat:[75,351]};townWalk(...positions[id],()=>{const t=townState();if(!t.seen.includes(id))t.seen.push(id);cpSave();townSay({lamp:'路灯：你们一牵手，这一小段路就亮了。回家的时候，我也会等着。',bench:'长椅给你们留了两个位置。坐一会儿吧，肩膀可以借你靠。',cat:'小猫蹭了蹭你们的鞋尖：喵。它好像也想跟着你们去看星星。'}[id])})};g.onclick=e=>{e.stopPropagation();fn()};g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fn()}}})}
const townBaseMap=renderCampaignMap;renderCampaignMap=function(){townBaseMap();townBind()};

const REWARD_THEMES={market:['星光集市','✦','#f2ce91'],memory:['琉璃回廊','◇','#a4d7ce'],water:['水车与风','≈','#a6cee1'],greenhouse:['月光温室','❀','#e8b2ce'],post:['迷雾邮局','✉','#c4b9ec']};
albumShowReward=function(){const p=ALBUM.find(p=>p.id===albumReward);if(!p)return;const [place,symbol,tint]=REWARD_THEMES[p.id];cpFrame('小镇替我们，留住了这一刻。','打开信封，让这一张回忆慢慢显影。',`<div class="keepsake-scene" data-theme="${p.id}" style="--keepsake-tint:${tint}"><div class="keepsake-sparks" aria-hidden="true">${Array.from({length:12},(_,i)=>`<i style="--n:${i}">${symbol}</i>`).join('')}</div><button id="rewardOpen" class="keepsake-envelope" aria-label="打开${place}寄来的回忆信封"><span class="keepsake-flap"></span><span class="keepsake-seal">${symbol}</span><span class="keepsake-address">TO US<br><small>${place} · 寄给两个人</small></span><span class="keepsake-open-label">轻点，打开这封回忆</span></button><div class="album-reward keepsake-reveal" hidden><figure class="album-polaroid"><div class="keepsake-develop">${albumImage(p)}<span></span></div><figcaption>${p.title}</figcaption></figure><div><div class="eyebrow">A MOMENT OF US · ${albumOwned().length} / 5</div><h3>原来，<br>这一刻也被好好记着。</h3><p>${p.line}</p><span class="keepsake-postmark">${place} ✦ 已珍藏</span><p><small>点照片放大看看。等回家，一起把它挂起来。</small></p></div></div></div>`,cpButton('albumKeep','收进回忆册，继续旅程 →','primary'));const keep=document.querySelector('#albumKeep');keep.hidden=true;document.querySelector('#rewardOpen').onclick=()=>{const s=document.querySelector('.keepsake-scene');s.classList.add('opened');document.querySelector('#rewardOpen').hidden=true;document.querySelector('.keepsake-reveal').hidden=false;keep.hidden=false;document.querySelector('.album-polaroid').onclick=()=>albumEnlarge(p);chime(true);if(!motionOff())keep.focus({preventScroll:true})};keep.onclick=()=>{albumReward=null;cpMap()}}

function roomLayout(){const a=albumState(),ids=ALBUM.map(p=>p.id);if(!Array.isArray(a.layout)||a.layout.length!==5||new Set(a.layout).size!==5||!a.layout.every(id=>ids.includes(id)))a.layout=[...ids];return a.layout}
function roomPlace(id,index){const a=albumState(),layout=roomLayout();if(!albumOwned().some(p=>p.id===id)||index<0||index>=5)return;const from=layout.indexOf(id);[layout[from],layout[index]]=[layout[index],layout[from]];if(!a.hung.includes(id))a.hung.push(id);roomSelection=null;cpSave();chime();render()}
function roomStartDrag(e,id){if(e.button!==0||!albumOwned().some(p=>p.id===id))return;const b=e.currentTarget;b.setPointerCapture(e.pointerId);roomDrag={id,owner:e.pointerId,startX:e.clientX,startY:e.clientY,moved:false};b.onpointermove=ev=>{if(!roomDrag||ev.pointerId!==roomDrag.owner)return;if(Math.hypot(ev.clientX-roomDrag.startX,ev.clientY-roomDrag.startY)>8){roomDrag.moved=true;let ghost=document.querySelector('#roomDragGhost');if(!ghost){ghost=document.createElement('div');ghost.id='roomDragGhost';ghost.innerHTML=albumImage(ALBUM.find(p=>p.id===id));document.body.append(ghost)}ghost.style.left=ev.clientX+'px';ghost.style.top=ev.clientY+'px';document.querySelectorAll('[data-room-slot]').forEach(slot=>{const r=slot.getBoundingClientRect();slot.classList.toggle('drop-ready',ev.clientX>=r.left&&ev.clientX<=r.right&&ev.clientY>=r.top&&ev.clientY<=r.bottom)})}};const end=ev=>{if(!roomDrag||ev.pointerId!==roomDrag.owner)return;const drag=roomDrag;roomDrag=null;document.querySelector('#roomDragGhost')?.remove();document.querySelectorAll('.drop-ready').forEach(el=>el.classList.remove('drop-ready'));if(drag.moved){roomIgnoreClick=performance.now()+400;const slot=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-room-slot]');if(slot)roomPlace(id,Number(slot.dataset.roomSlot))}};b.onpointerup=end;b.onpointercancel=()=>{roomDrag=null;document.querySelector('#roomDragGhost')?.remove();document.querySelectorAll('.drop-ready').forEach(el=>el.classList.remove('drop-ready'))};b.onlostpointercapture=()=>{if(roomDrag?.owner===e.pointerId){roomDrag=null;document.querySelector('#roomDragGhost')?.remove()}}}
albumHome=function(){const a=albumState(),owned=albumOwned(),layout=roomLayout(),ready=owned.length===5&&owned.every(p=>a.hung.includes(p.id)),count=a.hung.length;cpFrame('这一间小屋，终于有了我们的模样。','把照片从口袋拖进相框，也可以点选照片后再点相框。挂好的照片可以交换位置。',`<div class="album-room room-living ${ready?'room-complete':''}" style="--room-warmth:${count/5}"><div class="album-wall"><div class="room-fairy-lights" aria-label="已有${count}盏回忆灯亮起">${ALBUM.map((p,i)=>`<span class="${i<count?'on':''}"></span>`).join('')}</div><div class="album-wall-label">OUR LITTLE HOME · 一张合照，一盏灯</div><div class="album-wall-grid">${layout.map((id,i)=>{const p=ALBUM.find(p=>p.id===id),hung=a.hung.includes(id);return `<button class="album-wall-frame ${hung?'hung':''}" data-hang="${id}" data-room-slot="${i}" style="--tilt:${[-5,3,-2,4,-3][i]}deg" aria-label="第${i+1}个相框${hung?'，'+p.title:'，点击放入合照'}">${hung?albumImage(p):'<span>＋<small>把喜欢放在这里</small></span>'}<small>${hung?p.title:'空相框 '+(i+1)}</small></button>`}).join('')}</div><div class="album-shelf"><span>❀</span><i></i><span>▤</span></div><div class="room-sofa"></div><div class="album-room-pair"><svg viewBox="0 0 1000 140" aria-label="两个人靠在一起，坐在照片墙下"><defs>${daylightDefs}</defs>${character(465,78,true)+character(525,78,false)}</svg></div></div><div class="album-home-note"><div class="room-window" aria-label="小屋窗外的星空"><div class="room-window-stars">✦　·<br>　☾<br>·　✧</div><span></span><i></i><b></b></div><h3>${ready?'每一盏灯，都是我们。':'替回忆找个喜欢的位置。'}</h3><p id="roomPlacementStatus" role="status">${ready?'窗外的星星也准备好了。靠近一点，今晚的烟花要开始了。':roomSelection?'已经选好照片了。点一个相框，把它挂上去。':`已经点亮 ${count} / 5 盏回忆灯。`}</p>${ready?cpButton('albumFireworks',a.celebrated?'再靠在一起，看一场烟花 ✨':'牵着手，去窗边看烟花 ✨','primary'):''}<button id="albumOpenBook" class="control">翻开回忆册 · ${owned.length}/5</button><button id="gift" class="text" ${a.celebrated?'':'hidden'}>还有一件礼物，想交给你 →</button></div></div><div class="room-pocket"><span>口袋里的合照</span><div>${owned.map(p=>`<button class="room-pocket-photo ${a.hung.includes(p.id)?'placed':''} ${roomSelection===p.id?'selected':''}" data-pocket="${p.id}" aria-label="选择或拖动${p.title}">${albumImage(p)}<small>${a.hung.includes(p.id)?'✓ ':''}${p.title}</small></button>`).join('')||'<p>通关获得的合照，会收在这里。</p>'}</div><small>拖动布置 · 点选放置 · 挂好后点照片可放大</small></div>`,cpButton('albumBack','回到小镇地图','text'));document.querySelector('#cpMessage').textContent=ready?'照片都在，灯也都亮着。以后，还要一起把这面墙慢慢填满。':'每挂上一张照片，小屋就多亮一盏灯。';document.querySelectorAll('[data-pocket]').forEach(b=>{b.onpointerdown=e=>roomStartDrag(e,b.dataset.pocket);b.onclick=()=>{if(performance.now()<roomIgnoreClick)return;roomSelection=b.dataset.pocket;document.querySelectorAll('[data-pocket]').forEach(p=>p.classList.toggle('selected',p===b));document.querySelector('#roomPlacementStatus').textContent='选好了。点一个相框，把这张合照放进去。'}});document.querySelectorAll('[data-room-slot]').forEach(b=>{const id=b.dataset.hang;if(a.hung.includes(id))b.onpointerdown=e=>roomStartDrag(e,id);b.onclick=()=>{if(performance.now()<roomIgnoreClick)return;if(roomSelection)roomPlace(roomSelection,Number(b.dataset.roomSlot));else if(a.hung.includes(id))albumEnlarge(ALBUM.find(p=>p.id===id));else if(owned.some(p=>p.id===id))roomPlace(id,Number(b.dataset.roomSlot))}});document.querySelector('#albumOpenBook').onclick=albumInventory;document.querySelector('#albumBack').onclick=cpMap;document.querySelector('#albumFireworks')?.addEventListener('click',albumFireworks);document.querySelector('#gift').onclick=albumGift}
const windowBaseFireworks=albumFireworks;albumFireworks=function(){windowBaseFireworks();const d=document.querySelector('.album-fireworks');d.classList.add('through-window');d.insertAdjacentHTML('afterbegin','<div class="fire-window-frame" aria-hidden="true"><i></i><b></b></div>')};
const enchantBaseRender=render;render=function(){cancelAnimationFrame(townWalkFrame);++townWalkEpoch;enchantBaseRender();if(stage===0&&!campaign.active&&!memory.active){document.querySelector('.album-intro .eyebrow').textContent='A LITTLE WALK · 星光回忆版';chapter.textContent='PROLOGUE · 星光回忆版'}if(campaign.active==='map'){document.querySelector('.cp-heading h2').textContent='牵着手，把暮光小镇逛成我们的回忆。';document.querySelector('.cp-heading p').textContent='星光回忆版 · 可以散步的小镇、慢慢显影的合照、亲手布置的照片小屋。'}};
window.addEventListener('blur',()=>{roomDrag=null;document.querySelector('#roomDragGhost')?.remove()});
render();
